fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // Ensure the first array is non-empty.
    assert!(
        !first.is_empty(),
        "The first array must contain at least one element."
    );

    // Pre-allocate exactly the needed capacity:
    // (all but the last element of `first`) + (all elements of `second`).
    let mut replaced_list = Vec::with_capacity(first.len() - 1 + second.len());

    // Push all elements of `first` except its last.
    replaced_list.extend_from_slice(&first[..first.len() - 1]);

    // Append all elements of `second`.
    replaced_list.extend_from_slice(&second);

    replaced_list
}

